actions.script:
import java.sql.Timestamp

Timestamp effectiveLogDate = logDate ?: ec.user.nowTimestamp
Calendar cal = ec.user.getCalendarSafe()
cal.setTimeInMillis(effectiveLogDate.time)
cal.set(Calendar.MINUTE, 0)
cal.set(Calendar.SECOND, 0)
cal.set(Calendar.MILLISECOND, 0)
Timestamp binStartDateTime = new Timestamp(cal.timeInMillis)
cal.add(Calendar.HOUR_OF_DAY, 1)
Timestamp binEndDateTime = new Timestamp(cal.timeInMillis)

Closure<String> norm = { Object value ->
    String text = value != null ? value.toString().trim() : ''
    return text ? text : '_'
}
String binKey = [
        norm(toolName), norm(documentKind), norm(area), norm(subArea),
        norm(domainObject), norm(actionKind), norm(operationEffect),
        norm(executionChannel), norm(serviceName), norm(searchMode), norm(indexName)
].join('|')

def binValue = ec.entity.find('moqui.agent.AgentToolExecutionBin')
        .condition('binStartDateTime', binStartDateTime)
        .condition('binKey', binKey)
        .forUpdate(true)
        .one()
boolean exists = binValue != null
if (binValue) binValue = binValue.cloneValue()
if (!binValue) {
    binValue = ec.entity.makeValue('moqui.agent.AgentToolExecutionBin')
    binValue.setSequencedIdPrimary()
    agentToolExecutionBinId = binValue.agentToolExecutionBinId
    binValue.binKey = binKey
    binValue.binStartDateTime = binStartDateTime
    binValue.binEndDateTime = binEndDateTime
    binValue.toolName = toolName
    binValue.documentKind = documentKind
    binValue.area = area
    binValue.subArea = subArea
    binValue.domainObject = domainObject
    binValue.actionKind = actionKind
    binValue.operationEffect = operationEffect
    binValue.executionChannel = executionChannel
    binValue.serviceName = serviceName
    binValue.searchMode = searchMode
    binValue.indexName = indexName
    binValue.executionCount = 0
    binValue.successCount = 0
    binValue.errorCount = 0
    binValue.deniedCount = 0
    binValue.confirmationRequiredCount = 0
    binValue.hybridLlmRerankCount = 0
    binValue.rerankerFallbackCount = 0
    binValue.totalTimeMillis = 0
    binValue.totalSquaredTime = 0
} else {
    agentToolExecutionBinId = binValue.agentToolExecutionBinId
}

BigDecimal rt = (runningTimeMillis ?: 0) as BigDecimal
binValue.executionCount = (binValue.executionCount ?: 0) + 1
if (Boolean.TRUE.equals(success) || success == 'Y') {
    binValue.successCount = (binValue.successCount ?: 0) + 1
} else {
    binValue.errorCount = (binValue.errorCount ?: 0) + 1
}
if ((resultStatus ?: '') == 'denied') binValue.deniedCount = (binValue.deniedCount ?: 0) + 1
if ((confirmed == 'N' || Boolean.FALSE.equals(confirmed)) && riskLevelEnumId) {
    binValue.confirmationRequiredCount = (binValue.confirmationRequiredCount ?: 0) + 1
}
if ((searchMode ?: '') == 'hybrid_llm_rerank') {
    binValue.hybridLlmRerankCount = (binValue.hybridLlmRerankCount ?: 0) + 1
}
if (rerankerFallbackUsed == 'Y' || Boolean.TRUE.equals(rerankerFallbackUsed)) {
    binValue.rerankerFallbackCount = (binValue.rerankerFallbackCount ?: 0) + 1
}

binValue.totalTimeMillis = (binValue.totalTimeMillis ?: 0) + rt
binValue.totalSquaredTime = (binValue.totalSquaredTime ?: 0) + (rt * rt)
if (binValue.minTimeMillis == null || rt < (binValue.minTimeMillis as BigDecimal)) binValue.minTimeMillis = rt
if (binValue.maxTimeMillis == null || rt > (binValue.maxTimeMillis as BigDecimal)) binValue.maxTimeMillis = rt
binValue.lastLogDate = effectiveLogDate

if (exists) {
    binValue.update()
} else {
    try {
        binValue.create()
    } catch (Throwable createFailure) {
        ec.message.clearErrors()
        def existingBin = ec.entity.find('moqui.agent.AgentToolExecutionBin')
                .condition('binStartDateTime', binStartDateTime)
                .condition('binKey', binKey)
                .forUpdate(true)
                .one()
        if (!existingBin) throw createFailure

        BigDecimal existingRt = (existingBin.runningTimeMillis ?: 0) as BigDecimal
        existingBin = existingBin.cloneValue()
        existingBin.executionCount = (existingBin.executionCount ?: 0) + 1
        if (Boolean.TRUE.equals(success) || success == 'Y') {
            existingBin.successCount = (existingBin.successCount ?: 0) + 1
        } else {
            existingBin.errorCount = (existingBin.errorCount ?: 0) + 1
        }
        if ((resultStatus ?: '') == 'denied') existingBin.deniedCount = (existingBin.deniedCount ?: 0) + 1
        if ((confirmed == 'N' || Boolean.FALSE.equals(confirmed)) && riskLevelEnumId) {
            existingBin.confirmationRequiredCount = (existingBin.confirmationRequiredCount ?: 0) + 1
        }
        if ((searchMode ?: '') == 'hybrid_llm_rerank') {
            existingBin.hybridLlmRerankCount = (existingBin.hybridLlmRerankCount ?: 0) + 1
        }
        if (rerankerFallbackUsed == 'Y' || Boolean.TRUE.equals(rerankerFallbackUsed)) {
            existingBin.rerankerFallbackCount = (existingBin.rerankerFallbackCount ?: 0) + 1
        }

        existingBin.totalTimeMillis = (existingBin.totalTimeMillis ?: 0) + rt
        existingBin.totalSquaredTime = (existingBin.totalSquaredTime ?: 0) + (rt * rt)
        if (existingBin.minTimeMillis == null || rt < (existingBin.minTimeMillis as BigDecimal)) existingBin.minTimeMillis = rt
        if (existingBin.maxTimeMillis == null || rt > (existingBin.maxTimeMillis as BigDecimal)) existingBin.maxTimeMillis = rt
        existingBin.lastLogDate = effectiveLogDate
        agentToolExecutionBinId = existingBin.agentToolExecutionBinId
        existingBin.update()
    }
}

import org.moqui.agent.AgentConfigUtil
boolean bestEffortTelemetry = AgentConfigUtil.getBoolean('moqui.agent.elasticTelemetry.bestEffort', true) def logValue = ec.entity.makeValue('moqui.agent.AgentToolExecutionElasticLog') logValue.setSequencedIdPrimary() agentToolExecutionElasticLogId = logValue.getPrimaryKeys().values().first() logValue.setAll([ agentToolExecutionElasticLogId : agentToolExecutionElasticLogId, agentToolExecutionLogId : agentToolExecutionLogId, logDate : logDate ?: ec.user.nowTimestamp, userId : userId ?: ec.user.userId, visitId : visitId ?: ec.user.visitId, mcpSessionId : mcpSessionId ?: visitId ?: ec.user.visitId, moquiTxId : moquiTxId, toolName : toolName, documentId : documentId, documentKind : documentKind, area : area, subArea : subArea, domainObject : domainObject, actionKind : actionKind, operationEffect : operationEffect, executionChannel : executionChannel, artifactTypeEnumId : artifactTypeEnumId, artifactName : artifactName, serviceName : serviceName, riskLevelEnumId : riskLevelEnumId, confirmed : Boolean.TRUE.equals(confirmed) ? 'Y' : 'N', success : Boolean.TRUE.equals(success) ? 'Y' : 'N', errorType : errorType, errorMessage : errorMessage, runningTimeMillis : runningTimeMillis, resultStatus : resultStatus, parameterSummary : parameterSummary, resultSummary : resultSummary, searchMode : searchMode, resultCount : resultCount, topDocumentId : topDocumentId, topScore : topScore, indexName : indexName, indexRunId : indexRunId, rerankerProvider : rerankerProvider, rerankerModel : rerankerModel, rerankerMode : rerankerMode, rerankerCandidateCount : rerankerCandidateCount, rerankerSelectedDocumentId : rerankerSelectedDocumentId, rerankerReasonCode : rerankerReasonCode, rerankerConfidence : rerankerConfidence, rerankerLatencyMillis : rerankerLatencyMillis, rerankerFallbackUsed : rerankerFallbackUsed, llmMathModelId : llmMathModelId, embeddingMathModelId : embeddingMathModelId, rerankerMathModelId : rerankerMathModelId, mathModelRunId : mathModelRunId ]) try { logValue.create() } catch (Throwable logFailure) { if (!bestEffortTelemetry) throw logFailure ec.message.clearErrors() ec.logger.warn("Skipping AgentToolExecutionElasticLog write for ${toolName}: ${logFailure.message ?: logFailure.toString()}") return }
try { ec.service.sync().name('org.moqui.agent.AgentTelemetryServices.count#AgentToolExecutionBin') .disableAuthz() .parameters([ logDate : logDate ?: ec.user.nowTimestamp, toolName : toolName, documentKind : documentKind, area : area, subArea : subArea, domainObject : domainObject, actionKind : actionKind, operationEffect : operationEffect, executionChannel : executionChannel, serviceName : serviceName, searchMode : searchMode, indexName : indexName, riskLevelEnumId : riskLevelEnumId, confirmed : confirmed, success : success, resultStatus : resultStatus, runningTimeMillis : runningTimeMillis, rerankerFallbackUsed : rerankerFallbackUsed ]).call() } catch (Throwable t) { ec.logger.warn("Unable to update AgentToolExecutionBin for ${toolName}: ${t.message}") }

import org.moqui.agent.AgentConfigUtil import org.moqui.agent.search.ElasticBackendAdapter
Closure<List<String>> resolveTelemetryIndexCandidates = { String explicitName -> LinkedHashSet<String> names = new LinkedHashSet<String>() if (explicitName) names.add(explicitName) String configured = AgentConfigUtil.getString('moqui.agent.telemetry.indexName', null) if (configured) names.add(configured) def dataDocument = ec.entity.find('moqui.entity.document.DataDocument') .disableAuthz() .condition('dataDocumentId', 'AgentToolExecLog') .one() if (dataDocument?.indexName) names.add(dataDocument.indexName as String) names.add('moqui_agent_telemetry_v1') names.add('agent_tool_exec_log') return names.findAll { it } as List<String> }
List<String> indexCandidates = resolveTelemetryIndexCandidates(indexName as String) String effectiveIndexName = indexCandidates.first() int effectiveLimit = Math.min(Math.max(limit ?: 500, 1), 5000)
def find = ec.entity.find('moqui.agent.AgentToolExecutionElasticLog').orderBy('-logDate').limit(effectiveLimit) if (visitId) find.condition('visitId', visitId) List<Map> docs = (find.list() ?: []).collect { ev -> Map row = [:] ev.getMap().each { k, v -> row[k] = v } row.doc_id = row.agentToolExecutionElasticLogId row }
def adapter = new ElasticBackendAdapter(ec) if (!adapter.indexExists(effectiveIndexName)) { adapter.createIndex(effectiveIndexName, [ mappings: [ properties: [ agentToolExecutionElasticLogId: [type:'keyword'], agentToolExecutionLogId: [type:'keyword'], logDate: [type:'date'], userId: [type:'keyword'], visitId: [type:'keyword'], mcpSessionId: [type:'keyword'], toolName: [type:'keyword'], documentId: [type:'keyword'], documentKind: [type:'keyword'], area: [type:'keyword'], subArea: [type:'keyword'], domainObject: [type:'keyword'], actionKind: [type:'keyword'], operationEffect: [type:'keyword'], executionChannel: [type:'keyword'], artifactTypeEnumId: [type:'keyword'], artifactName: [type:'keyword'], serviceName: [type:'keyword'], riskLevelEnumId: [type:'keyword'], confirmed: [type:'keyword'], success: [type:'keyword'], errorType: [type:'keyword'], errorMessage: [type:'text'], runningTimeMillis: [type:'double'], resultStatus: [type:'keyword'], parameterSummary: [type:'text'], resultSummary: [type:'text'], searchMode: [type:'keyword'], resultCount: [type:'integer'], topDocumentId: [type:'keyword'], topScore: [type:'double'], indexName: [type:'keyword'] ] ] ]) } if (docs) adapter.bulkIndex(effectiveIndexName, docs)
documentsIndexed = docs.size() indexNameUsed = effectiveIndexName

import org.moqui.agent.AgentConfigUtil
import org.moqui.agent.AgentToolSupport
import org.moqui.agent.search.ElasticBackendAdapter

int effectiveLimit = Math.min(Math.max(limit ?: 10, 1), 50)
String effectiveVisitId = (visitId ?: sessionId ?: ec.user.visitId) as String
Closure<List<String>> resolveTelemetryIndexCandidates = { String explicitName ->
    LinkedHashSet<String> names = new LinkedHashSet<String>()
    if (explicitName) names.add(explicitName)
    String configured = AgentConfigUtil.getString('moqui.agent.telemetry.indexName', null)
    if (configured) names.add(configured)
    def dataDocument = ec.entity.find('moqui.entity.document.DataDocument')
            .disableAuthz()
            .condition('dataDocumentId', 'AgentToolExecLog')
            .one()
    if (dataDocument?.indexName) names.add(dataDocument.indexName as String)
    names.add('moqui_agent_telemetry_v1')
    names.add('agent_tool_exec_log')
    return names.findAll { it } as List<String>
}

List<String> indexCandidates = resolveTelemetryIndexCandidates(indexName as String)
String effectiveIndexName = indexCandidates.first()

Closure enrichBusinessSummary = { Map row ->
    if (!row) return row
    boolean needsSummary = !row.resultSummary || row.resultSummary == 'resultKeys='
    if (!needsSummary && row.businessResultSummary) return row
    String txLogId = row.agentToolExecutionLogId as String
    if (!txLogId) return row
    try {
        def txLog = ec.entity.find('moqui.agent.AgentToolExecutionLog')
                .disableAuthz()
                .condition('agentToolExecutionLogId', txLogId)
                .one()
        Object parsedResult = AgentToolSupport.fromJson(txLog?.resultJson as String)
        if (parsedResult instanceof Map) {
            Map parsedMap = parsedResult as Map
            Map businessSummary =
                    ((parsedMap.businessObjects instanceof Map) || (parsedMap.actions instanceof Collection) || parsedMap.operation || parsedMap.planType) ?
                            parsedMap :
                            AgentToolSupport.buildBusinessResultSummary(parsedMap)
            if (businessSummary) {
                row.businessResultSummary = businessSummary
                if (!row.resultSummary || row.resultSummary == 'resultKeys=') {
                    row.resultSummary = AgentToolSupport.toJson(businessSummary)
                }
            }
        }
    } catch (Throwable ignored) { }
    return row
}

Map boolQuery = [filter: []]
if (effectiveVisitId) boolQuery.filter.add([term: [visitId: effectiveVisitId]])
if (toolName) boolQuery.filter.add([term: [toolName: toolName]])
if (documentId) boolQuery.filter.add([term: [documentId: documentId]])
if (serviceName) boolQuery.filter.add([term: [serviceName: serviceName]])
if (artifactName) boolQuery.filter.add([term: [artifactName: artifactName]])
if (Boolean.TRUE.equals(errorsOnly)) {
    boolQuery.filter.add([term: [success: 'N']])
} else if (success != null) {
    boolQuery.filter.add([term: [success: Boolean.TRUE.equals(success) ? 'Y' : 'N']])
}

Map querySpec = [
    size : effectiveLimit,
    sort : [[logDate: [order: 'desc']]],
    query: [bool: boolQuery]
]

List normalizedResultList = []
String sourceMode = 'entity_fallback'
Map searchRaw = [:]

try {
    def adapter = new ElasticBackendAdapter(ec)
    try {
        ec.service.sync().name('org.moqui.agent.AgentTelemetryServices.index#ToolExecutionLogs')
                .disableAuthz()
                .parameters([indexName: effectiveIndexName, limit: 500, visitId: effectiveVisitId]).call()
    } catch (Throwable ignored) { }
    for (String candidateIndexName in indexCandidates) {
        if (!adapter.indexExists(candidateIndexName)) continue
        effectiveIndexName = candidateIndexName
        searchRaw = adapter.search(candidateIndexName, querySpec) ?: [:]
        List hits = (((searchRaw.hits ?: [:]).hits ?: []) as List)
        normalizedResultList = hits.collect { Map hit ->
            Map src = (hit._source ?: [:]) as Map
            Map row = new LinkedHashMap(src)
            row._score = hit._score
            row._id = hit._id
            row.logSource = 'opensearch'
            enrichBusinessSummary(row)
        }
        sourceMode = 'opensearch'
        if (normalizedResultList) break
    }
} catch (Throwable t) {
    ec.logger.warn("search#ToolExecutionLogs OpenSearch lookup failed: ${t.message}")
}

if (!normalizedResultList) {
    try {
        def find = ec.entity.find('moqui.agent.AgentToolExecutionElasticLog')
        if (effectiveVisitId) find.condition('visitId', effectiveVisitId)
        if (toolName) find.condition('toolName', toolName)
        if (documentId) find.condition('documentId', documentId)
        if (serviceName) find.condition('serviceName', serviceName)
        if (artifactName) find.condition('artifactName', artifactName)
        if (Boolean.TRUE.equals(errorsOnly)) {
            find.condition('success', 'N')
        } else if (success != null) {
            find.condition('success', Boolean.TRUE.equals(success) ? 'Y' : 'N')
        }
        normalizedResultList = (find.orderBy('-logDate').limit(effectiveLimit).list() ?: []).collect { ev ->
            Map row = [:]
            ev.getMap().each { k, v -> row[k] = v }
            row.logSource = 'entity'
            enrichBusinessSummary(row)
        }
    } catch (Throwable t) {
        ec.logger.warn("search#ToolExecutionLogs logging-entity fallback failed: ${t.message}")
    }
}

if (!normalizedResultList) {
    def find = ec.entity.find('moqui.agent.AgentToolExecutionLog')
    if (effectiveVisitId) find.condition('visitId', effectiveVisitId)
    if (toolName) find.condition('toolName', toolName)
    if (documentId) find.condition('documentId', documentId)
    if (serviceName) find.condition('artifactName', serviceName)
    if (artifactName) find.condition('artifactName', artifactName)
    if (Boolean.TRUE.equals(errorsOnly)) {
        find.condition('success', 'N')
    } else if (success != null) {
        find.condition('success', Boolean.TRUE.equals(success) ? 'Y' : 'N')
    }
    normalizedResultList = (find.orderBy('-endDate').limit(effectiveLimit).list() ?: []).collect { ev ->
        Map row = [:]
        ev.getMap().each { k, v -> row[k] = v }
        row.logDate = row.endDate ?: row.startDate
        row.serviceName = row.artifactTypeEnumId == 'AT_SERVICE' ? row.artifactName : null
        row.resultStatus = row.success == 'Y' ? 'ok' : 'error'
        row.logSource = 'transactional_entity'
        enrichBusinessSummary(row)
    }
    if (normalizedResultList) sourceMode = 'transactional_entity_fallback'
}

resultList = normalizedResultList
topLog = normalizedResultList ? (normalizedResultList.first() as Map) : [:]
searchDebug = [
    modeUsed : sourceMode,
    indexName: effectiveIndexName,
    indexCandidates: indexCandidates,
    visitId  : effectiveVisitId,
    resultCount: normalizedResultList.size()
]
